import json, sys, re, html
d = json.load(open(sys.argv[1], encoding='utf-8'))
old = d['old']
def plainar(n): return html.unescape(re.sub(r'<[^>]+>', '', old[n]['ar'])).strip()
o1 = plainar('1'); a = 'بحالة جيدة وصالحة للاستعمال وخالية من أي عيوب تؤثر على الانتفاع بها'
assert a in o1
o13 = plainar('13'); o17 = plainar('17'); o19 = plainar('19'); o27 = plainar('27'); o29 = plainar('29')
b19 = 'المياه والكهرباء والصرف الصحي والخدمات'; assert b19 in o19
b27 = 'خلال مدة لا تقل عن (15) يومًا من تاريخ الإخطار.'; assert b27 in o27
b29 = 'المحاكم المختصة في إمارة دبي للفصل فيه، وتكون هذه المحاكم صاحبة الولاية القضائية الحصرية.'; assert b29 in o29

AR = {
1: o1.replace(a, 'بالحالة المثبتة في تقرير معاينة الاستلام الموقّع والمرفق بهذا العقد بوصفه الملحق (ب)، والذي يقرّ الطرفان بأنه السجل المتفق عليه لحالة العين المؤجرة عند التسليم'),
4: '''<b>الصيانة والإصلاحات.</b>
(أ) مسؤولية المستأجر: (1) أعمال الصيانة والإصلاحات البسيطة للعين المؤجرة متى كانت تكلفة واقعة الإصلاح الواحدة، وفق تقدير فريق الصيانة التابع للمؤجر أو مقاول معتمد من قبله، أقل من {{MINOR_REPAIR_THRESHOLD}} درهم؛ (2) جميع أعمال صيانة وإصلاح أي تعديلات أو إضافات أو تركيبات يجريها المستأجر، وإزالتها عند الاقتضاء؛ (3) صيانة أي تجهيزات غير أصلية قَبِل المستأجر صراحةً تحمّل صيانتها في الملحق (ب)؛ (4) إصلاح أي ضرر، أيّاً كانت تكلفته، ينشأ عن سوء استخدام المستأجر أو إهماله، أو عن الأشخاص الذين يسمح لهم بدخول العين المؤجرة، أو عن تأخره في الإبلاغ عن أي عطل.
(ب) مسؤولية المؤجر: (1) أي واقعة إصلاح تبلغ تكلفتها {{MINOR_REPAIR_THRESHOLD}} درهم أو أكثر، بكامل قيمتها وليس الفرق الزائد فقط؛ (2) جميع الأعمال الإنشائية، وأعمال العزل المائي، والبنية التحتية الرئيسية للكهرباء والسباكة والصرف، ومعدات التبريد المركزي / التشيلر، وأي أنظمة مشتركة على مستوى المبنى، أيّاً كانت تكلفتها؛ (3) أي تجهيزات غير أصلية لم يرد في الملحق (ب) قبول المستأجر بصيانتها.
(ج) الإبلاغ: يلتزم المستأجر بالإبلاغ عن أي عطل أو ضرر من خلال تطبيق "Ain Al Reem Living" أو كتابياً خلال ثمانٍ وأربعين (48) ساعة من علمه به، وإذا أدى التأخر في الإبلاغ إلى زيادة تكلفة الإصلاح، يتحمل المستأجر التكلفة الإضافية.
(د) يجوز للمؤجر تنفيذ الإصلاحات الواقعة ضمن مسؤولية المستأجر إذا لم يقم بها خلال مدة معقولة، وتحميل المستأجر تكلفتها الفعلية.''',
5: 'في تاريخ التسليم، يقوم الطرفان معاً بإعداد وتوقيع تقرير معاينة الاستلام (الملحق ب)، متضمناً حالة كل غرفة وكل تجهيز مع صور فوتوغرافية مؤرخة، وقراءات العدادات (ديوا، التبريد، الغاز)، وقائمة بأي تجهيزات غير أصلية مع بيان ما إذا كان المستأجر يقبل تحمّل صيانتها. ويُعدّ الطرفان معاً تقرير معاينة الإخلاء (الملحق ج) في يوم إعادة المفاتيح، وبنفس ترتيب الغرف. وفي حال امتناع المستأجر عن الحضور أو التوقيع، يُعتدّ بتقرير المؤجر المشهود عليه من ممثل ثانٍ والمرسل إلى عنوان المستأجر المعتمد للإخطارات في اليوم ذاته. ويلتزم كل من المؤجر والمستأجر بالاحتفاظ بنسخة من هذين التقريرين، كما يلتزمان بتوثيق أي ملاحظات أو تعديلات تطرأ على حالة العين المؤجرة طوال فترة الإيجار.',
12: '''<b>سداد الإيجار والشيكات المرتجعة.</b>
(أ) يلتزم المستأجر بسداد الإيجار في تواريخ الاستحقاق المبيّنة في جدول الدفعات (الملحق أ)، وتُعدّ تواريخ الشيكات الواردة في الملحق (أ) تواريخ استحقاق الأقساط المعنية.
(ب) في حال ارتجاع أي شيك دون صرف لأي سبب يعود إلى المستأجر، يلتزم المستأجر خلال سبعة (7) أيام من تاريخ الإخطار الكتابي بما يلي:
(1) سداد قيمة الشيك المرتجع؛
(2) تعويض المؤجر عن التكاليف الفعلية المدفوعة للغير والناشئة عن الارتجاع، بما في ذلك الرسوم البنكية وتكاليف توجيه الإخطارات، مقابل نسخ من الإيصالات ذات الصلة؛
(3) سداد رسم إداري لمعالجة الشيك المرتجع قدره {{CHEQUE_ADMIN_FEE}} درهم عن كل شيك مرتجع. ويتفق الطرفان على أن هذا الرسم يمثّل تقديراً مسبقاً وحقيقياً للتكلفة الداخلية التي يتكبدها المؤجر في معالجة الشيك المرتجع (وقت الموظفين، والمراسلات، وإعادة تقديم الشيك، وحفظ السجلات)، وليس غرامة.
(ج) يجوز للمؤجر إصدار فاتورة بالمبالغ الواردة في البندين (ب)(2) و(ب)(3)، وفي حال عدم سدادها، خصمها من مبلغ التأمين وفقاً لبند مبلغ التأمين. كما يجوز للمؤجر أن يشترط سداد هذه المبالغ لقبول الشيك البديل.
(د) يُعدّ ارتجاع الشيك بسبب إغلاق الحساب، أو عدم مطابقة التوقيع، أو اختلاف المبلغ المكتوب بالحروف عن المبلغ المكتوب بالأرقام، إخلالاً جوهرياً بالعقد.
(هـ) يكون قبول المؤجر لشيك بديل أو لدفعة جزئية على الحساب فقط، ولا يترتب عليه تمديد أي تاريخ استحقاق أو التنازل عن أي إخطار سبق توجيهه أو عن أي حق من حقوق المؤجر.
(و) في حال عدم السداد، يحق للمؤجر ممارسة حقوقه المنصوص عليها في المادة (25) من القانون رقم (26) لسنة 2007 وتعديلاته، بما في ذلك توجيه الإخطار القانوني عن طريق الكاتب العدل أو البريد المسجل، والمطالبة بالإيجار حتى تاريخ الإخلاء الفعلي للعين المؤجرة وتسليمها.
(ز) تظل أحكام البندين (ب) و(ج) سارية بعد انتهاء هذا العقد أو فسخه.''',
13: o13 + ' ويلتزم المؤجر بتسجيل العقد في نظام إيجاري خلال {{EJARI_REGISTRATION_DAYS}} أيام عمل من تاريخ صرف القسط الأول واستلام مستندات المستأجر، ولا يجيز هذا البند للمؤجر الامتناع عن تسجيل العقد في نظام إيجاري متى استُوفيت هذه الشروط.',
15: '''<b>التجديد وتعديل الشروط.</b>
(أ) على الطرف الراغب في تعديل قيمة الإيجار أو أي شرط من شروط العقد للفترة الإيجارية التالية إخطار الطرف الآخر كتابياً قبل تسعين (90) يوماً على الأقل من تاريخ انتهاء العقد، ويجب أن تكون أي زيادة في الإيجار ضمن الحدود المقررة في مؤشر الإيجارات الصادر عن مؤسسة التنظيم العقاري (ريرا) والساري في حينه.
(ب) في حال عدم توجيه هذا الإخطار واستمرار المستأجر في إشغال العين المؤجرة، يتجدد العقد لمدة مماثلة وبالشروط ذاتها، وذلك وفقاً للمادة (6) من القانون رقم (26) لسنة 2007 وتعديلاته.
(ج) لا يجوز للمؤجر رفض التجديد إلا للأسباب ووفقاً لمدد الإخطار وطرقه المنصوص عليها في المادة (25)(2) من القانون رقم (26) لسنة 2007 وتعديلاته.
(د) على المستأجر الذي لا يرغب في التجديد إخطار المؤجر كتابياً قبل تسعين (90) يوماً على الأقل من تاريخ انتهاء العقد لتمكينه من إعادة التأجير، وفي حال تقديم الإخطار بعد هذه المدة، يظل المستأجر ملزماً بسداد الإيجار حتى تاريخ انتهاء العقد أو تاريخ التسليم الفعلي، أيهما لاحق، ويبذل المؤجر جهداً معقولاً لإعادة تأجير العين المؤجرة.''',
17: '(أ) ' + o17 + '''
(ب) الإشغال: لا يجوز أن يشغل العين المؤجرة إلا المستأجر والأشخاص المدرجون في الملحق (ب)، على ألا يتجاوز عددهم {{MAX_OCCUPANTS}} أشخاص، بصفتهم {{OCCUPANCY_TYPE_AR}}. ويُحظر استخدام العين المؤجرة كبيت عطلات أو سكن قصير الأجل أو سكن مشترك أو سكن عزاب، أو أي استخدام يخالف أنظمة الجهة المختصة بالمنطقة (بما في ذلك "تراخيص" أو بلدية دبي). ويلتزم المستأجر بأن يردّ للمؤجر أي غرامة أو جزاء يُفرض عليه نتيجة استخدام المستأجر، وذلك خلال سبعة (7) أيام من تاريخ المطالبة.
(ج) صلاحية الموافقة: لا تُلزم المؤجرَ أيُّ موافقة أو إذن أو شهادة عدم ممانعة ما لم تصدر على الورق الرسمي للمؤجر، وتحمل رقماً مرجعياً، وتكون موقّعة من مفوّض بالتوقيع مذكور في الرخصة التجارية للمؤجر أو بموجب وكالة مصدّقة لدى الكاتب العدل. ولا يملك الوسطاء العقاريون أو الوكلاء أو موظفو المبنى أي صلاحية لإصدار موافقات أو مستندات نيابةً عن المؤجر.''',
19: o19.replace(b19, 'المياه والكهرباء والصرف الصحي ورسوم التبريد المركزي / التشيلر والغاز والاتصالات والإنترنت والخدمات'),
21: '''<b>مبلغ التأمين.</b>
(أ) خلال سبعة (7) أيام عمل من تاريخ إتمام تقرير معاينة الإخلاء (الملحق ج)، يرسل المؤجر إلى المستأجر بياناً مفصلاً بالخصومات، يُشار فيه لكل بند إلى الملحقين (ب) و(ج) مع الصور الفوتوغرافية والسعر المعتمد من جدول الأسعار (الملحق د)، أو، بالنسبة للبنود غير المدرجة في الملحق (د)، تكلفة الإصلاح المثبتة بعرض سعر أو فاتورة من مقاول. وفي حال إمكانية تحديد جميع الخصومات من الملحق (د)، يجوز إصدار البيان وتوقيعه أثناء معاينة الإخلاء ذاتها.
(ب) يحق للمستأجر الاعتراض كتابياً خلال خمسة (5) أيام عمل من تاريخ الاستلام. ولا يوقف اعتراض المستأجر حق المؤجر في تنفيذ الإصلاحات أو أعمال التجهيز أو إعادة تأجير العين المؤجرة. ويُفصل في أي نزاع بشأن أي خصم استناداً إلى تقرير معاينة الاستلام (الملحق ب)، وتقرير معاينة الإخلاء (الملحق ج)، والصور الفوتوغرافية المرفقة بهما، وجدول الأسعار (الملحق د). ويُردّ الرصيد غير المتنازع عليه من مبلغ التأمين خلال خمسة وعشرين (25) يوم عمل من تاريخ تقديم المستأجر شهادات براءة الذمة النهائية من هيئة كهرباء ومياه دبي (ديوا)، والتبريد المركزي / التشيلر، والغاز، والاتصالات / الإنترنت، وإعادة جميع المفاتيح وبطاقات الدخول.
(ج) لا يُخصم أي مبلغ مقابل الاستهلاك العادي، والذي يشمل الخدوش والعلامات البسيطة، وثقوب المسامير الصغيرة، وبهتان الألوان بفعل أشعة الشمس، وإعادة الطلاء الاعتيادية بعد إيجار مدته اثنا عشر (12) شهراً أو أكثر، ما لم يُثبت وجود ضرر محدد.
(د) يحق للمؤجر أن يخصم الإيجار غير المسدد، ورسوم الخدمات غير المسددة، وأي مبالغ غير مسددة صدرت بها فواتير بموجب البند 12(ب) مؤيدة بالفاتورة والإيصالات، وتكلفة استبدال المفاتيح أو بطاقات الدخول غير المعادة وفق الأسعار الواردة في الملحق (د)، وتكلفة إصلاح الأضرار التي تتجاوز الاستهلاك العادي والمثبتة بالملحقين (ب) و(ج).''',
27: o27.replace(b27, 'خلال مدة لا تقل عن ثلاثين (30) يوماً من تاريخ الإخطار، على أن يوجَّه الإخطار وفقاً للمادة (25)(1)(ح) من القانون رقم (26) لسنة 2007 وتعديلاته.'),
'rent': 'يستمر استحقاق الإيجار بالقيمة المتفق عليها في العقد إلى أن يعيد المستأجر جميع المفاتيح وبطاقات الدخول ويتم توقيع تقرير معاينة الإخلاء (الملحق ج) أو إصداره، بما في ذلك أي فترة إشغال بعد انتهاء العقد أو فسخه، وتُحتسب هذه الفترة على أساس يومي تناسبي.',
'notice': 'عنوان المستأجر للإخطارات التعاقدية هو العين المؤجرة، والبريد الإلكتروني {{TENANT_EMAIL}}، ورقم الهاتف المتحرك {{TENANT_PHONE}}. وعنوان المؤجر للإخطارات هو المكتب P01، أيلا ريزيدنس، البرشاء جنوب الرابعة، دبي، والبريد الإلكتروني {{LANDLORD_NOTICE_EMAIL}}. وتُعتبر الإخطارات المرسلة بالبريد الإلكتروني أو بالبريد المسجل إلى هذه العناوين مستلَمةً في يوم العمل التالي. ويلتزم المستأجر بإخطار المؤجر كتابياً بأي تغيير في بيانات الاتصال خلال سبعة (7) أيام، وتكون الإخطارات المرسلة إلى آخر بيانات تم الإخطار بها صحيحة. أما الإخطارات القانونية بموجب القانون رقم (26) لسنة 2007 فتُوجَّه بالإضافة إلى ذلك بالطرق التي ينص عليها ذلك القانون.',
'keys': 'يقرّ المستأجر باستلام المفاتيح وبطاقات الدخول المدرجة في الملحق (ب)، ويلتزم بإعادتها جميعاً في تاريخ التسليم. ويتحمل المستأجر تكلفة استبدال أي مفتاح أو بطاقة دخول غير معادة أو تالفة وفق ما هو مدرج في الملحق (ب).',
'guar': 'يكفل {{GUARANTOR_NAME}} (رقم الهوية الإماراتية {{GUARANTOR_EID}}) كفالةً غير قابلة للإلغاء وغير مشروطة، بصفته مديناً أصلياً، سداد جميع مبالغ الإيجار وأي مبالغ أخرى مستحقة على المستأجر بموجب هذا العقد، وتنفيذ المستأجر لالتزاماته، ويوقّع على هذا العقد بهذه الصفة.',
29: o29.replace(b29, 'مركز فض المنازعات الإيجارية في إمارة دبي، وفقاً للمرسوم رقم (26) لسنة 2013، للفصل فيه، ويكون هذا المركز صاحب الولاية القضائية الحصرية.'),
}
import os
ANNEX = [
 ('Annex A - Payment Schedule', 'الملحق (أ) - جدول الدفعات'),
 ('Annex B - Move-In Inspection Report', 'الملحق (ب) - تقرير معاينة الاستلام'),
 ('Annex C - Move-Out Inspection Report', 'الملحق (ج) - تقرير معاينة الإخلاء'),
 ('Annex D — Schedule of Rates. The Parties agree that the rates below are a fair pre-estimate of the cost of repair, replacement or cleaning of the listed items and shall be applied in the deduction statement under the Security Deposit clause. Items not listed are charged at the actual cost evidenced by a contractor\'s quotation or invoice. Rates include labour and materials and exclude VAT where applicable.',
  'الملحق (د) - جدول الأسعار. يتفق الطرفان على أن الأسعار الواردة أدناه تمثّل تقديراً مسبقاً عادلاً لتكلفة إصلاح أو استبدال أو تنظيف البنود المدرجة، وتُطبَّق في بيان الخصومات بموجب بند مبلغ التأمين. وتُحتسب البنود غير المدرجة بالتكلفة الفعلية المثبتة بعرض سعر أو فاتورة من مقاول. وتشمل الأسعار تكلفة العمالة والمواد، ولا تشمل ضريبة القيمة المضافة حيثما تنطبق.'),
]
if os.path.exists(sys.argv[3]) and len(sys.argv) > 4:
    fx = json.load(open(sys.argv[3], encoding='utf-8'))
    for k in list(AR.keys()):
        AR[k] = fx[str(k)]
    ANNEX = [tuple(x) for x in fx['annex']]
def plain(t):
    t = t.replace('&nbsp;', ' ').replace('<br>', '\n')
    t = re.sub(r'<(?!/?b>)[^>]+>', '', t)
    return html.unescape(t).strip()
def esc(t):
    t = html.escape(t).replace('&lt;b&gt;', '<b>').replace('&lt;/b&gt;', '</b>')
    return t.replace('\n', '<br>')
key = {'new - Rent until actual vacating': 'rent', 'new - Notices and addresses for service': 'notice',
       'new - Keys and access cards': 'keys', 'new - Guarantor (only when a guarantor is on the lease)': 'guar'}
rows = []
for x in d['mapping']:
    if not x.get('pending') or not x['en']: continue
    k = x['old'] if x['old'] else key[x['kind']]
    num = x['new'] if x['new'] else f"{x['position_after']+1}*"
    en_t = plain(x["en"])
    if k == 'guar': en_t = en_t.replace('as principal obligor,', 'as principal obligor, jointly and severally with the Tenant,')
    rows.append(f'<tr><td class="no">{num}</td><td class="en">{esc(en_t)}</td><td class="ar" dir="rtl">{esc(AR[k])}</td></tr>')
for en, ar in ANNEX:
    rows.append(f'<tr><td class="no">Annex</td><td class="en">{esc(en)}</td><td class="ar" dir="rtl">{esc(ar)}</td></tr>')
